/* @autogenerated */
package net.civeira.phylax.features.document.rendering.domain;

/**
 * Desired output format for the rendering engine.
 *
 * <p>
 * The use case passes this flag via {@code TemplateRenderRequest} so that the gateway can
 * post-process the raw Handlebars output accordingly.
 */
public enum TemplateOutputFormat {

  /**
   * Standard HTML output. CSS assets are listed in the result but kept as external references;
   * callers are responsible for linking them in the page.
   */
  HTML,

  /**
   * Self-contained HTML. Every CSS asset in the request is injected as a {@code <style>} block
   * inside the document {@code <head>}, making the document suitable for email clients or sandboxed
   * frames that cannot load external stylesheets.
   */
  HTML_EMBEDDED,

  /**
   * Plain Markdown text. Reserved for future use.
   */
  MARKDOWN,

  /**
   * PDF binary output. Reserved for future use.
   */
  PDF
}
